const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const n = parseInt(input.trim(), 10);
    let prev = 1;
    let now = 2;
    let ans = 0;

    while (now <= n) {
        const next = prev + now;
        prev = now;
        now = next;
        ans += 1;
    }

    console.log(ans);
    rl.close();
});

